"""Real browser checks over disposable canonical objects, never production storage."""
import json


def run_time_view_checks(*,cdp,e,check,wait_for,add,click,shot):
    q=json.dumps
    galaxy=add('Time review')
    branch=add('Japan Trip',galaxy)
    item=add('Flight with a deliberately long title to test truncation',branch)
    ongoing=add('Ongoing journey',branch)
    future=add('Next month trip',branch)
    e(f'createChildEntry({q(branch)},true);fields[0].value="Travel tasks";form.requestSubmit();applicationCommandTail')
    wait_for('!formSaveBusy');task_list=e('selectedNode.dataset.entryId')
    task=add('Book hotel',task_list)
    done=add('Passport checked',task_list)
    today=e('cosmosTime.key(new Date())')
    e(f'window.timeFixture={{galaxy:{q(galaxy)},branch:{q(branch)},item:{q(item)},ongoing:{q(ongoing)},task:{q(task)},done:{q(done)},future:{q(future)}}};window.timeToday={q(today)}')
    e(f'saveEntryTime({q(item)},"when",{{startDate:timeToday,endDate:null,time:"14:30"}})')
    e(f'saveEntryTime({q(ongoing)},"when",{{startDate:cosmosTime.addDays(timeToday,-3),endDate:cosmosTime.addDays(timeToday,10),time:null}})')
    e(f'saveEntryTime({q(future)},"when",{{startDate:cosmosTime.shiftMonth(timeToday,1),endDate:null,time:null}})')
    e(f'saveEntryTime({q(task)},"due",{{date:timeToday,time:"09:00"}})')
    e(f'saveEntryTime({q(done)},"due",{{date:timeToday,time:null}})')
    e(f'changeTask({q(done)},"completed",true)')
    e('physics.pause();camera.stopAnimation();graphNeedsSave=false;window.timeBeforeView={...camera.view};setInspectorOpen(true)')
    e("document.getElementById('time-open').scrollIntoView({block:'nearest'})");click('#time-open')
    check(e("timeWorkspace.active&&!timeWorkspace.root.hidden&&timeWorkspace.nav.getAttribute('aria-current')==='page'"),'Time is a destination with an active navigation state')
    check(e("(()=>{const a=document.querySelector('#time-open > span').getBoundingClientRect(),b=document.querySelector('#tasks-toggle > span').getBoundingClientRect();return Math.abs(a.left-b.left)<1&&!timeWorkspace.nav.hasAttribute('aria-expanded')})()"),'Time label aligns with existing major navigation and has no accordion state')
    check(e("document.querySelectorAll('#time-calendar .time-week').length>=4&&document.querySelectorAll('#time-calendar .time-weekdays > span').length===7"),'Month calendar renders a familiar seven-column grid')
    check(e("!panel.hidden&&getComputedStyle(panel).display!=='none'"),'desktop keeps the existing Contents panel available')
    check(e('JSON.stringify(camera.view)===JSON.stringify(timeBeforeView)'),'opening Time preserves the camera')
    check(e("getComputedStyle(timeWorkspace.upcomingList).flexDirection==='row'"),'desktop Upcoming uses a horizontal strip')
    check(e("document.querySelectorAll('#time-upcoming-entries [data-time-group]').length===new Set(cosmosTime.upcoming(timeWorkspace.events,timeToday).map(x=>x.start<timeToday?timeToday:x.start)).size"),'Upcoming has exactly one group/node per effective chronological date')
    check(e("[...document.querySelectorAll('#time-upcoming-entries .temporal-avatar')].every(a=>entries.has(a.dataset.sourceId))&&!document.querySelector('#time-workspace canvas,#time-workspace .entry-node')"),'Upcoming avatars use canonical sources without mounting live renderer nodes')
    e('timeWorkspace.selectDay(timeToday)')
    check(e(f'!!document.querySelector(\'#time-day-entries [data-time-entry-id="{done}"].time-completed\')&&!document.querySelector(\'#time-upcoming-entries [data-time-entry-id="{done}"]\')'),'completed task remains checked in Calendar day entries and is excluded from Upcoming')
    check(e("document.querySelectorAll('#time-calendar .time-range').length>=2"),'date range continues across multiple calendar weeks')
    check(e("document.querySelector('#time-upcoming-entries').textContent.includes('Ongoing')"),'ongoing range remains visible in Upcoming')
    e(f'document.querySelector(\'#time-calendar [data-time-entry-id="{task}"]\').click()')
    check(e(f'timeWorkspace.active&&selectedNode.dataset.entryId==={q(task)}&&!panel.hidden&&contentInspector.entryId==={q(task)}'),'Calendar event selects canonical object in existing Contents and keeps Time visible')
    check(e('JSON.stringify(camera.view)===JSON.stringify(timeBeforeView)'),'Calendar selection leaves camera unchanged')
    check(e(f"document.querySelector('#time-calendar [data-time-entry-id={q(task)}]').dataset.selected==='true'"),'Calendar selection uses the approved active event paint')
    check(e(f"document.querySelector('#time-upcoming-entries [data-time-entry-id={q(task)}] .temporal-avatar').dataset.sourceId==={q(task_list)}"),'Task avatar inherits its actual owning Task List identity')
    e(f'document.querySelector(\'#time-upcoming-entries [data-time-entry-id="{task}"]\').click()')
    check(e(f'selectedNode.dataset.entryId==={q(task)}&&document.getElementById("content-time-label").textContent==="DUE"&&timeWorkspace.active'),'Upcoming task opens existing Due and Task contents')
    e(f'changeTask({q(task)},"completed",true)')
    check(e(f'timeWorkspace.active&&!document.querySelector(\'#time-upcoming-entries [data-time-entry-id="{task}"]\')'),'checking Done in Contents keeps Time active and refreshes Upcoming')
    e(f'changeTask({q(task)},"completed",false)')
    e(f'saveEntryTime({q(item)},"when",{{startDate:timeToday,endDate:null,time:"15:45"}})')
    check(e(f'timeWorkspace.events.find(x=>x.id==={q(item)}).time==="15:45"'),'existing When editor publication refreshes Time')
    e("window.timeOriginalMonth=timeWorkspace.month");click('#time-next');check(e('timeWorkspace.month===cosmosTime.shiftMonth(timeOriginalMonth,1)'),'Next month advances')
    click('#time-previous');check(e('timeWorkspace.month===timeOriginalMonth'),'Previous month returns')
    e("timeWorkspace.month='2026-12-01';timeWorkspace.render()");click('#time-next');check(e("timeWorkspace.month==='2027-01-01'"),'December advances to January')
    click('#time-today');check(e('timeWorkspace.month===timeToday.slice(0,7)+"-01"&&timeWorkspace.selectedDay===timeToday'),'Today returns and selects local today')
    check(e("document.querySelector('#time-calendar [aria-current=date]')?.getAttribute('aria-label').includes('entries')"),'calendar date accessible name includes full date and entry count')
    e('document.querySelector(`#time-calendar [data-time-day="${timeToday}"]`).focus()')
    cdp.call('Input.dispatchKeyEvent',type='keyDown',key='ArrowRight',code='ArrowRight',windowsVirtualKeyCode=39)
    cdp.call('Input.dispatchKeyEvent',type='keyUp',key='ArrowRight',code='ArrowRight',windowsVirtualKeyCode=39)
    check(e('timeWorkspace.selectedDay===cosmosTime.addDays(timeToday,1)&&document.activeElement.dataset.timeDay===timeWorkspace.selectedDay'),'keyboard arrow moves selected date and focus')
    # Dense days expose overflow without unbounded calendar row growth.
    e('window.timeOriginalEvents=timeWorkspace.events;timeWorkspace.events=[...timeWorkspace.events,...Array.from({length:12},(_,i)=>({...timeWorkspace.events.find(x=>x.id===timeFixture.item),id:`dense-${i}`}))];timeWorkspace.render()')
    check(e("!!document.querySelector('#time-calendar .time-more')&&document.querySelectorAll('#time-upcoming-entries [data-time-entry-id]').length>8"),'dense day exposes overflow and keeps all Upcoming entries in date groups')
    e('timeWorkspace.selectDay(timeToday)');check(e("document.querySelectorAll('#time-day-entries > li').length>=12"),'day selection reveals all overflow entries')
    e('timeWorkspace.refresh()')
    # Populated design fixture: these writes exist only in this disposable browser profile.
    health=add('Health',galaxy);dentist=add('Dentist',health)
    work=add('Work',galaxy);school=add('School',galaxy)
    def checklist(parent,name):
        e(f'createChildEntry({q(parent)},true);fields[0].value={q(name)};form.requestSubmit();applicationCommandTail')
        wait_for('!formSaveBusy');return e('selectedNode.dataset.entryId')
    work_list=checklist(work,'Office tasks');report=add('Finish report',work_list)
    school_list=checklist(school,'Course tasks');exam=add('Statistics assignment',school_list)
    reservation=add('Hotel check-in',branch)
    # Pick another ordinary Travel branch with a different stable silhouette.
    other_travel=None
    for name in ['Mexico Trip','Brazil Trip','Norway Trip','Italy Trip','Canada Trip']:
        candidate=add(name,galaxy)
        if e(f'cosmosTime.context(entries,entries.get({q(candidate)})).variant!==cosmosTime.context(entries,entries.get({q(branch)})).variant'):
            other_travel=candidate;break
    second_trip=add('Travel reservation',other_travel or candidate)
    for entry,kind,offset,clock in [(dentist,'when',0,'14:30'),(report,'due',0,'17:00'),(exam,'due',1,'23:59'),(reservation,'when',3,'15:00'),(second_trip,'when',5,'10:00')]:
        value=f'{{date:cosmosTime.addDays(timeToday,{offset}),time:{q(clock)}}}' if kind=='due' else f'{{startDate:cosmosTime.addDays(timeToday,{offset}),endDate:null,time:{q(clock)}}}'
        e(f'saveEntryTime({q(entry)},{q(kind)},{value})')
    # Earlier month events give the Calendar a realistic mix, without bloating Upcoming.
    for parent,name,day,clock in [(work,'Team meeting','06','10:00'),(health,'Dental checkup','14','09:30'),(school,'Study session','19','13:00'),(branch,'Flight tickets','09','11:00'),(work,'Client review','16','15:00'),(school,'Final exam','21','09:00'),(health,'Doctor visit','02','14:00')]:
        entry=add(name,parent)
        e(f'saveEntryTime({q(entry)},"when",{{startDate:timeToday.slice(0,8)+{q(day)},endDate:null,time:{q(clock)}}})')
    e(f'selectEntry(entries.get({q(ongoing)}),nodes.get({q(ongoing)}),{{openInspector:true,fromTime:true}});physics.pause();camera.stopAnimation();timeWorkspace.open();timeWorkspace.selectedDay=null;timeWorkspace.render();timeWorkspace.root.scrollTop=0')
    check(e('timeWorkspace.events.some(x=>x.context.family==="health")&&timeWorkspace.events.some(x=>x.context.family==="education")&&timeWorkspace.events.some(x=>x.context.family==="work")&&cosmosTime.upcoming(timeWorkspace.events,timeToday).length>=8'),'visual fixture includes Health, Work, School, two Travel contexts and populated Upcoming')
    for width,height,name in [(1440,900,'wide'),(1280,800,'laptop'),(1200,768,'narrow-desktop')]:
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=height,deviceScaleFactor=1,mobile=False)
        e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
        check(e('timeWorkspace.root.scrollWidth<=timeWorkspace.root.clientWidth+1&&document.documentElement.scrollWidth<=innerWidth'),'desktop '+name+': no horizontal page overflow')
        check(e('(()=>{const w=timeWorkspace.root.getBoundingClientRect(),p=panel.getBoundingClientRect(),s=hierarchySidebar.sidebar.getBoundingClientRect();return w.right<=p.left+1&&w.left>=s.right-1})()'),'desktop '+name+': Time occupies center between existing panels')
        check(e("!document.getElementById('time-back')&&!document.querySelector('.time-header-orbit')"),'desktop '+name+': redundant Back button removed')
        overflow=e("[...document.querySelectorAll('#time-calendar .time-day-events')].filter(list=>list.getBoundingClientRect().bottom>list.closest('.time-week').getBoundingClientRect().bottom+1).map(list=>({list:list.getBoundingClientRect().toJSON(),week:list.closest('.time-week').getBoundingClientRect().toJSON(),html:list.innerHTML}))")
        check(not overflow,'desktop '+name+': readable event and overflow rows stay inside Calendar weeks: '+json.dumps(overflow))
        check(e("timeWorkspace.strip.scrollHeight<=timeWorkspace.strip.clientHeight+1"),'desktop '+name+': Upcoming cards have no vertical clipping or nested vertical scroll')
        print('TIME GEOMETRY '+name+' '+json.dumps(e("(()=>{const m=document.querySelector('.time-month').getBoundingClientRect(),u=document.querySelector('.time-upcoming').getBoundingClientRect();return {calendarHeight:m.height,upcomingHeight:u.height,upcomingBottom:u.bottom,viewport:innerHeight,rootScroll:timeWorkspace.root.scrollHeight-timeWorkspace.root.clientHeight}})()")),flush=True)
        if name in ['wide','laptop']:
            check(e("(()=>{const r=timeWorkspace.root;r.scrollTop=r.scrollHeight;const last=timeWorkspace.upcomingList.lastElementChild.getBoundingClientRect();const visible=last.bottom<=r.getBoundingClientRect().bottom;r.scrollTop=0;return visible})()"),'desktop '+name+': dense same-day groups remain fully reachable by workspace scrolling')
        check(e("!document.querySelector('#time-workspace .time-icon,#time-workspace .time-task-badge')&&[...document.querySelectorAll('#time-upcoming-entries .temporal-avatar')].every(a=>a.getBoundingClientRect().width===28)"),'desktop '+name+': Calendar has no semantic icons/badges and Upcoming uses 28px source CBs')
        check(e("[...document.querySelectorAll('#time-calendar .time-day-events .time-event')].every(b=>{const r=b.getBoundingClientRect(),d=b.closest('.time-day').getBoundingClientRect();return r.left>=d.left&&r.right<=d.right&&r.bottom<=d.bottom-1})"),'desktop '+name+': actual event rectangles are bounded by their date cell')
        check(e("getComputedStyle(document.querySelector('.time-weeks')).paddingBottom==='36px'"),'desktop '+name+': approved final-week bottom zone is intact')
        check(e("[...document.querySelectorAll('#time-calendar .time-range')].every(b=>{const r=b.getBoundingClientRect(),w=b.closest('.time-week'),s=getComputedStyle(b),first=w.children[Number(s.gridColumnStart)-1].getBoundingClientRect(),last=w.children[Number(s.gridColumnEnd)-2].getBoundingClientRect(),row=w.getBoundingClientRect();return r.left>=first.left&&r.right<=last.right&&r.top>=row.top&&r.bottom<=row.bottom})"),'desktop '+name+': range segments align to exact date columns and remain in their week')
        check(e("[...document.querySelectorAll('.time-upcoming-event')].every(b=>{const s=getComputedStyle(b);return s.backgroundColor==='rgba(0, 0, 0, 0)'&&s.borderWidth==='0px'&&s.boxShadow==='none'})"),'desktop '+name+': Upcoming events never gain cards or boxes')
        shot('time-'+name)
        if name=='wide':
            e('timeWorkspace.root.style.filter="grayscale(1)"');shot('time-wide-no-color');e('timeWorkspace.root.style.filter=""')
            e('timeWorkspace.strip.scrollLeft=timeWorkspace.strip.scrollWidth');shot('time-wide-upcoming-later');e('timeWorkspace.strip.scrollLeft=0')
            e('timeWorkspace.selectDay(timeToday)');shot('time-wide-selected-day');e('timeWorkspace.selectedDay=null;timeWorkspace.render();timeWorkspace.root.scrollTop=0')
        e('setInspectorOpen(false);timeWorkspace.root.scrollTop=0');shot('time-'+name+'-contents-closed')
        check(e("document.querySelector('.time-upcoming').getBoundingClientRect().right<=innerWidth&&timeWorkspace.root.scrollWidth<=timeWorkspace.root.clientWidth+1"),'desktop '+name+': Calendar and Upcoming adapt with Contents closed')
        e('setInspectorOpen(true);timeWorkspace.root.scrollTop=0')
    e(f'focusEntry({q(branch)},{{openInspector:true}});camera.stopAnimation()')
    check(e('!timeWorkspace.active&&getComputedStyle(graphViewport).visibility!=="hidden"'),'normal Universe navigation exits Time')
    e('window.timeBeforeView={...camera.view};document.getElementById("time-open").scrollIntoView({block:"nearest"})');click('#time-open');click('#universe-home')
    check(e('!timeWorkspace.active&&JSON.stringify(camera.view)===JSON.stringify(timeBeforeView)'),'Back to Universe preserves prior canvas position')
    for width,height,name in [(390,844,'portrait'),(320,568,'narrow-portrait'),(740,390,'landscape')]:
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=height,deviceScaleFactor=1,mobile=True)
        e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));hierarchySidebar.setCollapsed(false)')
        e("document.getElementById('time-open').scrollIntoView({block:'nearest'})");click('#time-open')
        check(e('timeWorkspace.active&&hierarchySidebar.collapsed&&panel.hidden'),'mobile '+name+': drawer closes and Time opens')
        check(e("getComputedStyle(document.getElementById('mobile-body-actions')).display==='none'&&parseFloat(getComputedStyle(timeWorkspace.root).paddingLeft)<20"),'mobile '+name+': canvas Compact Preview is hidden and Calendar uses full width')
        check(e('(()=>{const r=timeWorkspace.root.getBoundingClientRect();return r.left===0&&r.right===innerWidth&&timeWorkspace.root.scrollWidth<=timeWorkspace.root.clientWidth+1})()'),'mobile '+name+': dedicated full-width surface without overflow')
        check(e("getComputedStyle(timeWorkspace.upcomingList).flexDirection==='column'&&getComputedStyle(document.querySelector('.time-date-markers')).display==='flex'"),'mobile '+name+': vertical Upcoming and context-colored date bars')
        click('#time-today')
        e('document.querySelector(`[data-time-day="${timeToday}"]`).scrollIntoView({block:"center"})');click(f'[data-time-day="{today}"]')
        check(e('timeWorkspace.selectedDay===timeToday&&!timeWorkspace.days.hidden&&document.querySelectorAll("#time-day-entries > li").length>=4'),'mobile '+name+': selected day exposes entry list')
        check(e("[...document.querySelectorAll('.time-date-markers')].every(m=>m.querySelectorAll('.time-date-bar').length<=3)&&!!document.querySelector('.time-date-overflow')"),'mobile '+name+': populated dates cap at three context bars plus overflow')
        check(e("getComputedStyle(document.querySelector('.time-date-bar')).width===(innerWidth<=350?'14px':'18px')&&getComputedStyle(document.querySelector('.time-date-bar')).height==='2px'"),'mobile '+name+': approved responsive context-bar dimensions')
        selector=f'#time-day-entries [data-time-entry-id="{task}"]'
        e(f'document.querySelector({q(selector)}).scrollIntoView({{block:"center"}})');click(selector)
        check(e(f'timeWorkspace.active&&!panel.hidden&&contentInspector.entryId==={q(task)}&&panel.dataset.contentsState==="browse"'),'mobile '+name+': event opens canonical Contents sheet')
        shot('time-mobile-contents-'+name)
        click('#close-inspector-button')
        check(e('timeWorkspace.active&&panel.hidden&&!timeWorkspace.root.inert&&document.activeElement.closest("#time-workspace")!==null'),'mobile '+name+': closing Contents returns focus to Time')
        e('timeWorkspace.root.scrollTop=0');shot('time-mobile-'+name)
        if name=='portrait':
            e('timeWorkspace.root.style.filter="grayscale(1)"');shot('time-mobile-no-color');e('timeWorkspace.root.style.filter=""')
        e("document.getElementById('time-upcoming-title').scrollIntoView({block:'start'})");shot('time-mobile-upcoming-'+name)
        check(e("document.getElementById('time-upcoming-title').getBoundingClientRect().top>=document.querySelector('.time-header').getBoundingClientRect().bottom"),'mobile '+name+': Upcoming stays clear of the persistent Time navigation header')
        e('timeWorkspace.root.scrollTop=0')
        e('window.timeBeforeView={...camera.view}');e('hierarchySidebar.setCollapsed(false)');e("document.getElementById('universe-home').scrollIntoView({block:'nearest'});document.getElementById('universe-home').click()")
        check(e('!timeWorkspace.active&&JSON.stringify(camera.view)===JSON.stringify(timeBeforeView)'),'mobile '+name+': existing Universe navigation returns without camera reset')
    cdp.call('Emulation.clearDeviceMetricsOverride');e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
    cdp.call('Emulation.setDeviceMetricsOverride',width=1280,height=800,deviceScaleFactor=1,mobile=False)
    e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
    # Render empty and same-family cases without writing alternate event storage.
    e('timeWorkspace.open();timeWorkspace.events=[];timeWorkspace.selectedDay=null;timeWorkspace.render();timeWorkspace.root.scrollTop=0')
    check(e("document.querySelectorAll('#time-calendar .time-day').length>=28&&!document.getElementById('time-upcoming-empty').hidden"),'empty Calendar keeps month and lightweight Upcoming message')
    shot('time-empty-panels')
    e('timeWorkspace.close();window.timeAggregate=cosmosTime.aggregate;window.timeAggregateCalls=0;cosmosTime.aggregate=(...args)=>{timeAggregateCalls++;return timeAggregate(...args)};refreshTaskMetadata()')
    check(e('timeAggregateCalls===0'),'hidden Time performs no aggregation on canonical task refresh')
    e('cosmosTime.aggregate=timeAggregate;timeWorkspace.open()')
    # Exercise canonical writes before the transient, non-persisted collection below.
    from time_overdue_browser import run_time_overdue_checks
    run_time_overdue_checks(cdp=cdp,e=e,check=check,wait_for=wait_for,add=add,shot=shot)
    e('window.timeReviewCollection={id:"time-review-collection",name:"Time navigation collection",memberEntryIds:[timeFixture.branch]};constellations.set(timeReviewCollection.id,timeReviewCollection)')
    e('activateConstellation(timeReviewCollection.id);camera.stopAnimation()')
    check(e('!timeWorkspace.active&&activeConstellationId===timeReviewCollection.id'),'existing Constellation navigation exits Time into its normal view')
    e('exitConstellation();timeWorkspace.open()')
    check(e("[...timeWorkspace.root.querySelectorAll('[data-time-entry-id]')].every(b=>b.getAttribute('aria-label')?.includes('All day')||b.getAttribute('aria-label')?.includes(':'))"),'event identity and context have text accessible names independent of color')
    check(not cdp.errors,f'no Time browser exceptions: {cdp.errors}')
